import sys, json
from typing import List

class Solution:
    def numMatchingSubseq(self, s: str, words: List[str]) -> int:
        waiting = [[] for _ in range(26)]
        for i, word in enumerate(words):
            waiting[ord(word[0]) - 97].append((i, 1))

        ans = 0
        for ch in s:
            idx = ord(ch) - 97
            current = waiting[idx]
            waiting[idx] = []
            for wi, pos in current:
                word = words[wi]
                if pos == len(word):
                    ans += 1
                else:
                    waiting[ord(word[pos]) - 97].append((wi, pos + 1))
        return ans

