int numMatchingSubseq(char *s, char **words, int wordsSize) {
    int *head = (int *)malloc(26 * sizeof(int));
    int *next = (int *)malloc((size_t)wordsSize * sizeof(int));
    int *pos = (int *)malloc((size_t)wordsSize * sizeof(int));
    if (!head || (!next && wordsSize) || (!pos && wordsSize)) { free(head); free(next); free(pos); return 0; }
    for (int i = 0; i < 26; ++i) head[i] = -1;
    for (int i = 0; i < wordsSize; ++i) {
        pos[i] = 1;
        int c = words[i][0] - 'a';
        next[i] = head[c];
        head[c] = i;
    }

    int ans = 0;
    for (const char *p = s; *p; ++p) {
        int c = *p - 'a';
        int node = head[c];
        head[c] = -1;
        while (node != -1) {
            int saved = next[node];
            if (words[node][pos[node]] == '\0') {
                ans++;
            } else {
                int nc = words[node][pos[node]] - 'a';
                pos[node]++;
                next[node] = head[nc];
                head[nc] = node;
            }
            node = saved;
        }
    }

    free(head); free(next); free(pos);
    return ans;
}

