static void skipWs(const string& s, size_t& p) {
    while (p < s.size() && isspace((unsigned char)s[p])) ++p;
}

static string parseString(const string& s, size_t& p) {
    skipWs(s, p);
    if (p >= s.size() || s[p] != '"') throw runtime_error("bad string");
    ++p;
    string out;
    while (p < s.size()) {
        char c = s[p++];
        if (c == '"') return out;
        if (c == '\\' && p < s.size()) c = s[p++];
        out.push_back(c);
    }
    throw runtime_error("unterminated string");
}

static vector<string> parseStringArray(const string& s, size_t& p) {
    skipWs(s, p);
    if (p >= s.size() || s[p] != '[') throw runtime_error("bad array");
    ++p;
    vector<string> out;
    skipWs(s, p);
    if (p < s.size() && s[p] == ']') { ++p; return out; }
    while (true) {
        out.push_back(parseString(s, p));
        skipWs(s, p);
        if (p >= s.size()) throw runtime_error("bad array end");
        if (s[p] == ']') { ++p; break; }
        if (s[p] != ',') throw runtime_error("bad separator");
        ++p;
    }
    return out;
}

