import java.io.*;
import java.util.*;

class Solution {
    public int numMatchingSubseq(String s, String[] words) {
        int n = words.length;
        int[] head = new int[26];
        int[] next = new int[n];
        int[] pos = new int[n];
        Arrays.fill(head, -1);
        Arrays.fill(next, -1);

        for (int i = 0; i < n; i++) {
            pos[i] = 1;
            int c = words[i].charAt(0) - 'a';
            next[i] = head[c];
            head[c] = i;
        }

        int ans = 0;
        for (int k = 0; k < s.length(); k++) {
            int c = s.charAt(k) - 'a';
            int node = head[c];
            head[c] = -1;
            while (node != -1) {
                int savedNext = next[node];
                if (pos[node] == words[node].length()) {
                    ans++;
                } else {
                    int nc = words[node].charAt(pos[node]) - 'a';
                    pos[node]++;
                    next[node] = head[nc];
                    head[nc] = node;
                }
                node = savedNext;
            }
        }
        return ans;
    }
}

public class Main {
    static final class Parser {
        final String s;
        int p = 0;
        Parser(String s) { this.s = s; }
        void ws() { while (p < s.length() && Character.isWhitespace(s.charAt(p))) p++; }
        void expect(char ch) { ws(); if (p >= s.length() || s.charAt(p) != ch) throw new IllegalArgumentException(); p++; }
        String parseString() {
            ws(); expect('\"');
            StringBuilder b = new StringBuilder();
            while (p < s.length()) {
                char c = s.charAt(p++);
                if (c == '\"') return b.toString();
                if (c == '\\') { if (p >= s.length()) throw new IllegalArgumentException(); b.append(s.charAt(p++)); }
                else b.append(c);
            }
            throw new IllegalArgumentException();
        }
        String[] parseStringArray() {
            ws(); expect('[');
            ws();
            if (s.charAt(p) == ']') { p++; return new String[0]; }
            ArrayList<String> list = new ArrayList<>();
            while (true) {
                list.add(parseString());
                ws();
                char c = s.charAt(p++);
                if (c == ']') break;
                if (c != ',') throw new IllegalArgumentException();
            }
            return list.toArray(new String[0]);
        }
        Object[] parseArgs() {
            ws(); expect('[');
            String s0 = parseString();
            ws(); expect(',');
            String[] words = parseStringArray();
            ws(); expect(']');
